arguments.command:
cd /app && python - <<'PY'
import requests
ids=open('pdb_ids.txt').read().split()
for p in ids:
 r=requests.get(f'https://data.rcsb.org/rest/v1/core/entry/{p}',timeout=20)
 try:
  d=r.json(); desc=d.get('struct',{}).get('title'); ents=d.get('rcsb_entry_container_identifiers',{}).get('polymer_entity_ids',[])
  print(p,desc,'entities',ents)
 except: print(p,r.status_code)
PY

