arguments.command:
python - <<'PY'
import urllib.request,json
for p in open('/app/pdb_ids.txt').read().split():
 try:
  d=json.load(urllib.request.urlopen(f'https://data.rcsb.org/rest/v1/core/entry/{p}',timeout=20))
  print(p,d.get('struct',{}).get('title'),d.get('rcsb_entry_container_identifiers',{}).get('polymer_entity_ids'))
 except Exception as e: print(p,e)
PY

